INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", 10, "", 1070016, 1, 1, "今思うと…最初のゲリラLIVEは\nほんとうにいっぱいいっぱいでしたね", 11, 112411);
