INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", 10, "", 1070021, 1, 1, "緊張してるのが見てて分かりましたよ\nなんだかこっちまで緊張して\nお腹が締め付けられる思いでしたよ～", 11, 105831);
INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", "", "", 1070022, "", "", "", 91, 0);
