INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", 10, "", 1070031, 1, 1, "まーたしかに、あのときの\nウヅキたちのゲリラLIVEは\nほんとにボロボロだったわね！", 11, 106031);
INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", "", "", 1070032, "", "", "", 91, 0);
