INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", 10, "", 1070036, 1, 1, "もうっ、キャルキャル～\nあんま言わないでよ～！\n私たちだってわかってるんだからさ～", 11, 112611);
INSERT INTO `v1_4135f2152c3f83afa1b5e9c7fd2d2463ecfe5a4caa011c567116b2a488762684` VALUES (7, "", "", "", "", 1070037, "", "", "", 91, 0);
